ee:message.ee:set-payload:
%dw 2.0
output application/java
---
[
    {
        Id : vars.caseId,
        Status : payload.status,
        Priority : payload.priority
    }
]

%dw 2.0
output application/json
---
if (payload.successful == true and (payload.items[0].payload.success default false) == true)
{
    "status" : "success",
    "message" : "Case updated successfully",
    "caseId" : vars.caseId
}
else
{
    "status" : "failed",
    "message" : payload.items[0].exception.localizedMessage default "Salesforce rejected Case update."
}

%dw 2.0
output application/json
---
if (isEmpty(payload))
{
    "status": "error",
    "message": "No cases found for contact ID: " ++ (vars.contactId default "")
}
else
{
    "status": "success",
    "data": payload map (item) -> {
        "caseId"      : item.Id,
        "subject"     : item.Subject,
        "description" : item.Description,
        "priority"    : item.Priority,
        "status"      : item.Status
    }
}

%dw 2.0
output application/json
---
// Safe navigation ensures it won't crash if items[0] or payload is weird
if (payload.successful == true and (payload.items[0].payload.success default false) == true)
{
    "status" : "success",
    "message" : "Case created successfully",
    "id" : payload.items[0].id
}
else
{
    "status" : "failed",
    "message" : payload.items[0].exception.localizedMessage default "Salesforce rejected Case creation. Check if ContactId exists and Priority is valid."
}
